import * as E from './tycoon-state.js?v=expansion15';
import {mountOffice} from './office-world.js?v=expansion15';
import {mountServerRoom} from './server-room.js?v=expansion15';
const KEY='kontur-tycoon-v1',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.round(n).toLocaleString('ru-RU'),time=n=>{n=Math.max(0,Math.ceil(n));return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');};
export function mountTycoon(root,{onQuest=()=>{},audio,startView='office',initialState=null,sandbox=false,openAt=null,profession=null}={}){
 const storageKey=sandbox?'kontur-admin-tycoon-v1':KEY;let state,view=startView,category='all',asset='ssd',disposed=false,raf,last=performance.now(),refreshTime=0,saveTime=0,worldCleanup=null,dialogCleanup=null,dialog=null,noticeTimer,form={qty:'1',limit:'600',margin:'250',leverage:'2',side:'long'};
 if(initialState)state=initialState;else try{state=E.restoreTycoon(localStorage.getItem(storageKey));}catch{state=E.createTycoon();}
 E.migrateTycoon(state);if(profession)state.profession=profession;
 const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('Хранилище браузера заполнено. Скачай сохранение.');}};
 function toast(text){let n=document.querySelector('#tycoon-toast');if(!n){n=document.createElement('div');n.id='tycoon-toast';document.body.append(n);}n.textContent=text;n.className='visible';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.className='',4000);}
 function act(fn,{redraw=true}={}){try{fn();save();audio?.transition();if(redraw)render();}catch(e){toast(e.message);}}
 const nav=[['office','⌑','Компания'],['cases','▧','Кейсы'],['stock','▤','Склад и люди'],['nds','▣','Техника НДС'],['market','⇄','Рынок'],['futures','⌁','Фьючерсы'],['zozon','◇','Зозон / аукцион'],['clans','⚑','Кланы'],['custom','⌂','Стиль базы'],['log','≡','Журнал']];
 const tabs=()=>`<div class="category-tabs">${E.CATEGORIES.filter(([id])=>view!=='nds'||!['relic','theme'].includes(id)).map(([id,name])=>`<button data-category="${id}" class="${category===id?'active':''}">${name}</button>`).join('')}</div>`;
 function listing(){return E.CATALOG.filter(p=>(view!=='nds'||!['relic','theme'].includes(p.cat))&&(category==='all'||p.cat===category));}
 function icon(p){return `<div class="asset-icon ${p.cat}">${p.icon}</div>`;}
 function render(){if(disposed)return;worldCleanup?.();worldCleanup=null;root.innerHTML=`<div class="tycoon-app profession-${state.profession||'frontend'} base-${state.theme}" style="--role:${E.PROFESSIONS[state.profession]?.accent||'#a8bbae'};--base:${E.item(state.theme).color}"><aside class="tycoon-sidebar"><div class="company-identity"><span>ЦЕНТР ИНВЕСТ БАНК / LAB</span><div class="profession-badge">${E.PROFESSIONS[state.profession]?.name||'Свободный профиль'}</div><h2>${esc(state.name)}</h2><small>${state.area} м² · ${E.activeWorkers(state).length}/${E.capacity(state)} мест</small></div><nav>${nav.map(([id,ico,label])=>`<button data-view="${id}" class="${view===id?'active':''}"><i>${ico}</i>${label}</button>`).join('')}</nav><div class="sim-note">Локальная симуляция<br>Лоты и соперники — NPC<button id="export-tycoon">Сохранить в файл ↓</button></div></aside><div class="tycoon-content"><header class="tycoon-toolbar"><div><span>КАПИТАЛ КОМПАНИИ</span><strong data-cash>${fmt(state.cash)} <small>CR</small></strong></div><div><span>МОЩНОСТЬ</span><strong data-power>${fmt(E.power(state))}</strong></div><div><span>КЛАНОВЫЙ БОНУС</span><strong>${Math.round(E.bonus(state.clan?.trophies)*100)}%</strong></div><label>Время симуляции<select id="sim-speed"><option value="0" ${state.speed===0?'selected':''}>Пауза</option><option value="1" ${state.speed===1?'selected':''}>1× / реальное</option><option value="10" ${state.speed===10?'selected':''}>10×</option><option value="60" ${state.speed===60?'selected':''}>60× / показ</option></select></label></header><section class="tycoon-view">${({office:office,cases:cases,stock:stock,nds:nds,market:()=>exchange(false),futures:()=>exchange(true),zozon:auction,clans:clans,log:history,custom:custom})[view]()}</section></div></div>`;
 root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;if(view==='nds'&&['relic','theme'].includes(category))category='all';if(['market','futures'].includes(view)&&state.speed===0)state.speed=1;render();});root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render();});root.querySelector('#sim-speed').onchange=e=>{state.speed=+e.target.value;save();};root.querySelector('#export-tycoon').onclick=()=>{save();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='kontur-tycoon-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};bind();}
 const heading=(tag,title,desc='')=>`<div class="tycoon-heading"><span class="eyebrow">${tag}</span><h1>${title}</h1>${desc?'<p>'+desc+'</p>':''}</div>`;
 function office(){const workers=E.activeWorkers(state);return heading('СТУДИЯ / СОБСТВЕННОСТЬ','Твоя точка роста.','Выполняй кейсы, оборудуй места и расширяй компанию без ограничения уровня.')+hardwarePanel()+`<div class="profession-benefit">${E.PROFESSIONS[state.profession]?.bonus||'Выбери профиль компании в главном меню'}</div><div class="company-top"><div class="isometric-office"><div class="iso-floor"></div>${Array.from({length:Math.min(8,Math.max(2,workers.length))},(_,i)=>`<div class="iso-desk" style="--n:${i}"><i></i><b></b><span>${workers[i]?'●':''}</span></div>`).join('')}<div class="office-preview-label">${state.area} м² <span>ОФИС / 2D ПЛАН</span></div><button id="walk-office" class="solid-button">Походить в 3D ↗</button></div><aside class="company-stats"><span>КОМПАНИЯ В ЦИФРАХ</span><div><b>${state.finished}</b><small>закрытых кейсов</small></div><div><b>${fmt(state.revenue)} CR</b><small>заработано на кейсах</small></div><div><b>${Object.values(state.installed).reduce((a,b)=>a+b,0)}</b><small>единиц оборудования установлено</small></div><button class="outline-button" data-goto="stock">Склад / установка →</button><button class="outline-button" id="expand-office">Купить +4 м² · 700 CR</button></aside></div><div class="tycoon-section-title"><h2>Что дальше?</h2><span>Расширение → люди → оборудование → кейс</span></div><div class="quick-actions"><button data-goto="cases"><b>01</b><strong>Взять кейс</strong><span>Команда приносит выручку</span></button><button data-goto="nds"><b>02</b><strong>Купить технику</strong><span>НДС · честная фиксированная цена</span></button><button data-goto="market"><b>03</b><strong>Открыть рынок</strong><span>Лимитные заявки и свои цены</span></button></div><label class="company-rename">Название компании<input id="company-name" maxlength="34" value="${esc(state.name)}"><button id="rename-company">Сохранить</button></label>`;}
 function cases(){const current=state.jobs.find(j=>!j.done);return heading('РАБОТА / КОМАНДА','Выбери следующий кейс.','Один Senior может заменить нескольких Junior. Специалист нужного профиля ускоряет кейс на 20%.')+`<div class="case-progress">${current?jobStatus(current):'<span>Команда свободна. Выбери заказ по силам.</span>'}</div><div class="store-grid">${E.CASES.map(c=>`<article class="case-card"><small>${c.role.toUpperCase()}</small><h2>${c.name}</h2><p>${c.desc}</p><div class="case-meta"><span>${c.need} мощности</span><b>+${fmt(c.reward)} CR</b></div><button class="solid-button" data-case="${c.id}" ${current||E.power(state)<c.need?'disabled':''}>${current?'Команда занята':E.power(state)<c.need?'Нужна более сильная команда':'Начать кейс →'}</button></article>`).join('')}</div><p class="subtle">Контракты специалистов действуют час игрового времени; зарплата за час списывается при активации. Без активных сотрудников кейс ждёт.</p>`;}
 function jobStatus(j){const c=E.CASES.find(c=>c.id===j.kind);return `<span>${c.name}</span><div class="thin-progress"><i style="width:${Math.min(100,j.progress/c.work*100)}%"></i></div><b>${Math.min(100,Math.floor(j.progress/c.work*100))}%</b>`;}
 function nds(){return hardwarePanel()+heading('НДС / МАГАЗИН ТЕХНИКИ','Оснащение компании.','Техника и контракты попадают на склад. SSD и RAM нужно физически установить в 3D.')+tabs()+`<div class="store-grid">${listing().map(p=>`<article class="store-card">${icon(p)}<small>${p.cat==='people'?'КОНТРАКТ СПЕЦИАЛИСТА':'НОВОЕ ОБОРУДОВАНИЕ'}</small><h2>${p.name}</h2><p>${p.desc}</p><footer><strong>${fmt(p.base)} CR</strong><button data-buy="${p.id}">Купить +</button></footer></article>`).join('')}</div>`;}
 function stock(){return relicPanel()+heading('СКЛАД / КОМПЛЕКТУЮЩИЕ И КОМАНДА','Покупка — только начало.','Активируй контракты сотрудников. Переноси оборудование со склада в 3D и устанавливай в сервер.')+`<div class="stock-summary"><span>${E.activeWorkers(state).length}/${E.capacity(state)} сотрудников</span><span>${state.area} м²</span><span>Бонусы дают только установленные предметы</span></div><div class="store-grid">${E.CATALOG.filter(p=>(state.inventory[p.id]||0)>0).map(p=>`<article class="store-card">${icon(p)}<small>НА СКЛАДЕ: ${state.inventory[p.id]}</small><h2>${p.name}</h2><p>${p.desc}</p><button class="outline-button" data-use="${p.id}">${p.skill?'Нанять на час · '+p.wage+' CR':p.id==='sqm'?'Расширить офис на 4 м²':p.cat==='relic'?'Активировать усиление':p.cat==='theme'?'Применить тему':'Установить в 3D →'}</button></article>`).join('')||'<p>Склад пуст. Купи предметы в НДС или на рынке.</p>'}</div><div class="tycoon-section-title"><h2>Активная команда</h2><span>Зарплата за час уже оплачена</span></div><div class="staff-list">${E.activeWorkers(state).map(w=>`<article><i>${w.role[0]}</i><div><b>${esc(w.name)}</b><span>${w.role} · ${w.skill} мощности</span></div><small data-until="${w.until}">${time(w.until-state.time)}</small></article>`).join('')||'<p class="subtle">Активных сотрудников пока нет. На начальном складе — два контракта Junior.</p>'}</div><div class="installed-list">${E.CATALOG.filter(p=>state.installed[p.id]).map(p=>`<span>✓ ${p.name} ×${state.installed[p.id]}</span>`).join('')}</div>`;}
 function chart(){const rows=state.history[asset].slice(-40),min=Math.min(...rows.map(r=>r.l))*.998,max=Math.max(...rows.map(r=>r.h))*1.002,y=v=>155-(v-min)/(max-min||1)*130;return `<svg class="price-chart" viewBox="0 0 640 190" role="img" aria-label="Свечной график цены ${esc(E.item(asset).name)}"><defs><linearGradient id="chart-glow" x2="0" y2="1"><stop stop-color="#76c1a1" stop-opacity=".14"/><stop offset="1" stop-color="#76c1a1" stop-opacity="0"/></linearGradient></defs>${[25,65,105,145].map(y=>`<line x1="0" x2="580" y1="${y}" y2="${y}" stroke="#a2b5bd18"/>`).join('')}${rows.map((r,i)=>{const x=10+i*14.1,c=r.c>=r.o?'#8dcaac':'#d79483';return `<line x1="${x+4}" x2="${x+4}" y1="${y(r.h)}" y2="${y(r.l)}" stroke="${c}"/><rect x="${x}" y="${Math.min(y(r.o),y(r.c))}" width="8" height="${Math.max(1,Math.abs(y(r.o)-y(r.c)))}" fill="${c}"/>`;}).join('')}<text x="582" y="28" fill="#8ca5ad" font-size="10">${fmt(max)}</text><text x="582" y="153" fill="#8ca5ad" font-size="10">${fmt(min)}</text><text x="10" y="182" fill="#6d8992" font-size="10">СВЕЧА / 5 СЕК ИГРОВОГО ВРЕМЕНИ</text></svg>`;}
 function exchange(futures){const p=E.item(asset),quote=E.price(state,asset);return heading(futures?'БИРЖА / БЕССРОЧНЫЕ КОНТРАКТЫ':'РЫНОК / СВОБОДНЫЕ ЦЕНЫ',futures?'Торгуй движением цены.':'У каждого лота своя цена.',futures?'Игровые фьючерсы: long / short, изолированный залог, плечо, комиссия и ликвидация. Товар на склад не поступает.':'Покупай товары, выставляй свои цены или оставляй лимитные заявки. В этой версии контрагенты — NPC.')+`<div class="exchange-status"><i></i> АКТИВНАЯ ТОРГОВЛЯ · NPC / ЛОКАЛЬНАЯ БИРЖА <span>Котировки обновляются каждые 5 игровых секунд</span></div>`+tabs()+`<div class="exchange-layout"><div class="exchange-main"><div class="asset-selector"><select id="asset-selector" aria-label="Товар для торговли">${listing().map(x=>`<option value="${x.id}" ${asset===x.id?'selected':''}>${x.name}</option>`).join('')}</select><strong data-price>${fmt(quote)} <small>CR</small></strong><span>${futures?'PERPETUAL / ИЗОЛИРОВАННЫЙ':'SPOT / ТОВАР НА СКЛАД'}</span></div><div id="chart-zone">${chart()}</div><div class="orderbook" id="live-book">${book()}</div></div><aside class="trade-ticket"><small>${futures?'ОТКРЫТЬ ПОЗИЦИЮ':'СОЗДАТЬ ЗАЯВКУ'}</small><h2>${p.name}</h2><p>${p.rarity?'<b>'+p.rarity+'</b> · ':''}${p.desc}</p>${futures?`<label>Направление<select data-form="side"><option value="long" ${form.side==='long'?'selected':''}>LONG / цена вверх</option><option value="short" ${form.side==='short'?'selected':''}>SHORT / цена вниз</option></select></label><label>Залог / CR<input type="number" min="50" data-form="margin" value="${form.margin}"></label><label>Плечо<select data-form="leverage">${[1,2,3,5,10].map(n=>`<option value="${n}" ${+form.leverage===n?'selected':''}>${n}×</option>`).join('')}</select></label><p>Комиссия входа и выхода: 0,06% от объёма. Funding: 0,01% в игровой час. При ликвидации теряется залог.</p><button class="solid-button" id="open-position">Открыть позицию</button>`:`<label>Количество<input type="number" min="1" max="1000" data-form="qty" value="${form.qty}"></label><label>Твоя цена / CR<input type="number" min="1" data-form="limit" value="${form.limit}"></label><p>На складе: ${state.inventory[asset]||0}. Комиссия лимитной заявки 0,5%. Резерв возвращается при отмене.</p><button class="solid-button" id="market-buy">Купить сейчас · ${fmt(quote*1.008)} CR/шт</button><button class="outline-button" id="market-sell">Продать сейчас</button><button class="outline-button" id="limit-buy">Лимитная покупка</button><button class="outline-button" id="limit-sell">Выставить свой лот</button>`}</aside></div>${futures?positions():orders()}`;}
 function orders(){return `<div class="tycoon-section-title"><h2>Мои заявки</h2><span>Средства и товары зарезервированы</span></div><div class="trade-rows">${state.orders.map(o=>`<article><b>${E.item(o.id).name}</b><span>${o.side==='sell'?'Продажа':'Покупка'} · ${o.qty} × ${fmt(o.limit)} CR</span><button data-cancel="${o.oid}">Отменить</button></article>`).join('')||'<p class="subtle">Открытых заявок нет.</p>'}</div>`;}
 function positions(){return `<div class="tycoon-section-title"><h2>Открытые позиции</h2><span>Позиции закрываются вручную или при ликвидации</span></div><div class="trade-rows">${state.positions.map(p=>`<article><div><b>${E.item(p.id).name}</b><small>${p.side.toUpperCase()} · ${p.leverage}× · вход ${fmt(p.entry)} · залог ${fmt(p.margin)}</small></div><span data-equity="${p.pid}">Капитал ${fmt(E.positionEquity(state,p))} CR</span><button data-close-position="${p.pid}">Закрыть</button></article>`).join('')||'<p class="subtle">Нет открытых позиций. Все расчёты происходят в CR внутри игры.</p>'}</div>`;}
 function auction(){const a=state.auction;return heading('ЗОЗОН / АУКЦИОНЫ','Кто предложит больше?','Выбери категорию и открой аукцион. Игровые соперники повышают ставки; средства резервируются до результата.')+tabs()+`<div class="auction-feature">${a?`${icon(E.item(a.id))}<div><small>${a.done?'АУКЦИОН ЗАВЕРШЁН':'ЛОТ / ОГРАНИЧЕННОЕ ВРЕМЯ'}</small><h2>${E.item(a.id).name}</h2><p>Лидер: ${a.bidder==='you'?'ты':esc(a.bidder)}</p><strong>${fmt(a.bid)} CR</strong><span data-until="${a.until}">${a.done?'Завершён':time(a.until-state.time)}</span><button class="solid-button" id="auction-bid" ${a.done?'disabled':''}>Повысить ставку до ${fmt(Math.ceil(a.bid*1.07))} CR</button></div>`:'<div><h2>Первый лот ждёт.</h2><p>Контракты, SSD, оперативка, процессоры, видеокарты, мониторы, кресла и площадь.</p></div>'}</div><div class="store-grid">${listing().map(p=>`<article class="store-card">${icon(p)}<h2>${p.name}</h2><p>Старт от ${fmt(E.price(state,p.id)*.55)} CR</p><button class="outline-button" data-auction="${p.id}" ${a&&!a.done?'disabled':''}>Открыть аукцион →</button></article>`).join('')}</div>`;}
 function clans(){const c=state.clan;return lootPanel()+heading('КЛАНЫ / КОМАНДНАЯ ЛИГА','Кубки имеют вес.','До 100 участников в клане. Победа даёт кубки всем, поражение их отнимает. Подбор соперника зависит от силы команды и рейтинга.')+(!c?`<div class="clan-intro"><div class="clan-emblem">⚑</div><div><h2>Найди своих.</h2><p>Создай клан или вступи в демонстрационный клан с игровыми участниками.</p><label>Название клана<input id="clan-name" maxlength="28" value="Контур"></label><div><button class="solid-button" id="create-clan">Создать клан</button><button class="outline-button" id="join-clan">Вступить в «Северный кластер»</button></div></div></div>`:`<div class="clan-feature"><div class="clan-emblem">⚑</div><div><small>ОБЩИЙ РЕЙТИНГ КЛАНА</small><h2>${esc(c.name)}</h2><strong>${fmt(c.trophies)} <span>кубков</span></strong><p>${c.members.length}/100 участников · ${c.wins} побед · ${c.losses} поражений</p><div class="clan-actions"><button class="solid-button" id="start-war" ${state.war||state.time<state.warReady?'disabled':''}>${state.war?'Война идёт':state.time<state.warReady?'Восстановление '+time(state.warReady-state.time):'Начать войну · 300 CR'}</button><button class="outline-button" id="add-member" ${c.members.length>=100?'disabled':''}>Добавить NPC-участника</button><button class="text-button" id="leave-clan">Выйти</button></div></div></div>${state.war?`<div class="war-progress"><span>ПРОТИВНИК / ${esc(state.war.opponent)}</span><h3>Командная операция идёт.</h3><b data-until="${state.war.until}">${time(state.war.until-state.time)}</b><p>Наша сила ${Math.round(state.war.own)} · соперник ${Math.round(state.war.enemy)}. Исход зависит от подготовки и противника.</p></div>`:''}`)+`<div class="tycoon-section-title"><h2>Бонус к выручке всех участников</h2><span>Порог не суммируется с предыдущим</span></div><div class="trophy-tiers">${[[1000,1],[2000,5],[5000,10],[7000,15],[10000,25]].map(([n,b])=>`<article class="${(c?.trophies||0)>=n?'reached':''}"><b>${fmt(n)}</b><span>кубков</span><strong>+${b}%</strong></article>`).join('')}</div>${c?`<div class="staff-list">${c.members.slice(0,100).map(m=>`<article><i>${m.id==='you'?'К':'·'}</i><div><b>${esc(m.name)}</b><span>${m.npc?'Игровой участник':'Ты'} · ${fmt(c.trophies)} общих кубков</span></div></article>`).join('')}</div>`:''}`;}

 function hardwarePanel(){const h=E.hardware(state);const missing=h.cpu<h.gpu?'cpu':'gpu',target=Math.abs(h.gpu-h.cpu),recommended=E.CATALOG.filter(p=>p.cat===missing&&p.power>=target).sort((a,b)=>a.base-b.base)[0];return `<section class="hardware-panel"><div><span>ВЫЧИСЛИТЕЛЬНЫЙ КЛАСТЕР</span><h2>${h.cpu||h.gpu?h.bottleneck:'Собери первую связку'}</h2><p>CPU и GPU работают парой. Мощность = 2 × меньший индекс. Избыток второго компонента простаивает.</p>${target&&recommended?'<p class="pair-tip">Для баланса добавь: <b>'+recommended.name+'</b> · индекс '+recommended.power+'</p>':''}</div><div class="hardware-bars"><label>CPU <b>${fmt(h.cpu)}</b></label><meter min="0" max="${Math.max(1,h.cpu,h.gpu)}" value="${h.cpu}"></meter><label>GPU <b>${fmt(h.gpu)}</b></label><meter min="0" max="${Math.max(1,h.cpu,h.gpu)}" value="${h.gpu}"></meter><strong>${Math.round(h.efficiency*100)}% общей загрузки</strong><small>Вычисления: ${fmt(h.power*.008*3600*(1+(E.buffs(state).compute||0))*E.revenueMultiplier(state))} CR/игровой час</small></div></section>`;}
 function relicPanel(){return `<section class="relic-slots"><div><span>АКТИВНЫЕ УСИЛЕНИЯ / ${(state.activeRelics||[]).length} ИЗ 3</span><p>Три разных предмета. Дубликаты можно продать на рынке.</p></div>${state.activeRelics.map(id=>`<article><b>${E.item(id).name}</b><small>${E.item(id).desc}</small><button data-unequip="${id}">Снять на склад</button></article>`).join('')}</section>`;}
 function lootPanel(){const last=state.loot[0];return `<section class="loot-panel"><span>КЛАНОВЫЙ КЕЙС / 1 ПРЕДМЕТ ЗА КАЖДУЮ ВОЙНУ</span><h2>${last?E.item(last.id).name:'Трофей ждёт в конце операции'}</h2><p>${last?E.item(last.id).rarity+' · '+E.item(last.id).desc:'Награда выдаётся автоматически и при победе, и при поражении. Активируй её на складе или продай.'}</p><details><summary>10 предметов · вероятности и эффекты</summary>${E.RELICS.map(x=>`<p><b>${x.name}</b> · ${x.rarity} · ${x.weight}% — ${x.desc}</p>`).join('')}</details><button data-goto="stock">Открыть склад →</button></section>`;}
 function custom(){return heading('ЗОЗОН / ИНТЕРЬЕРЫ','У базы есть характер.','Одна покупка открывает тему навсегда. Применяется к 2D-плану и 3D-офису.')+`<div class="theme-grid">${E.THEMES.map(t=>`<article style="--swatch:${t.color};--wall:${t.wall}"><div class="theme-preview"><i></i><i></i><i></i><b>${t.key==='hacker'?'◉ ◉':'ЦЕНТР ИНВЕСТ БАНК'}</b></div><h2>${t.name}</h2><button data-theme="${t.id}">${state.theme===t.id?'✓ Применена':state.themes.includes(t.id)?'Применить':fmt(t.base)+' CR · Купить'}</button></article>`).join('')}</div>`;}
 function book(){return `<header><span>ЦЕНА / CR</span><span>КОЛИЧЕСТВО</span><span>NPC + МОИ ЗАЯВКИ</span></header>${E.orderBook(state,asset).map(o=>`<div class="${o.side==='sell'?'ask':'bid'}"><b>${fmt(o.limit)}</b><span>${o.qty}${o.npc?'':' · МОЯ'}</span><i style="width:${Math.min(95,o.qty*3)}%"></i></div>`).join('')}`;}
 function history(){return heading('СОБЫТИЯ / ИСТОРИЯ КОМПАНИИ','Всё записано.')+`<div class="event-log">${state.log.map((t,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><p>${esc(t)}</p></article>`).join('')}</div>`;}
 function openDialog(body){dialogCleanup?.();if(dialog){dialog.close();dialog.remove();}dialog=document.createElement('dialog');dialog.className='tycoon-dialog';dialog.innerHTML=`<button class="modal-close" aria-label="Закрыть окно">×</button>${body}`;document.body.append(dialog);dialog.querySelector('.modal-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialogCleanup?.();dialogCleanup=null;dialog?.remove();dialog=null;save();render();},{once:true});dialog.showModal();}
 function installItem(id){if(id==='ssd'||id==='ram'){openDialog('<h2>Установка: '+E.item(id).name+'</h2><div id="installation-world"></div>');let reported=false;dialogCleanup=mountServerRoom(dialog.querySelector('#installation-world'),()=>{if(reported)return;reported=true;act(()=>E.install(state,id),{redraw:false});audio?.success();toast(E.item(id).name+' установлен.');},{installItem:id});}else openOffice(id);}
 function openOffice(){view='office';openDialog('<h2>Твоя компания / 3D</h2><p class="subtle">Коробки слева — купленное оборудование. Стойка справа — место установки. SSD и RAM также доступны через подробное обслуживание на складе.</p><div id="walking-office"></div>');dialogCleanup=mountOffice(dialog.querySelector('#walking-office'),state,{onInstalled:id=>{act(()=>E.install(state,id),{redraw:false});toast('Установлено: '+E.item(id).name);},onExit:()=>dialog.close()});}
 function bind(){root.querySelectorAll('[data-unequip]').forEach(b=>b.onclick=()=>act(()=>E.unequipRelic(state,b.dataset.unequip)));root.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>act(()=>{const id=b.dataset.theme;if(!state.themes.includes(id)){if(!(state.inventory[id]>0))E.buy(state,id);E.useItem(state,id);}else state.theme=id;}));root.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{view=b.dataset.goto;render();});root.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>act(()=>E.buy(state,b.dataset.buy)));root.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{const p=E.item(b.dataset.use);if(p.install)installItem(p.id);else act(()=>E.useItem(state,p.id));});root.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>act(()=>E.startCase(state,b.dataset.case)));root.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>act(()=>E.cancelOrder(state,b.dataset.cancel)));root.querySelectorAll('[data-close-position]').forEach(b=>b.onclick=()=>act(()=>E.closePosition(state,b.dataset.closePosition)));root.querySelectorAll('[data-auction]').forEach(b=>b.onclick=()=>act(()=>E.makeAuction(state,b.dataset.auction)));root.querySelectorAll('[data-form]').forEach(e=>e.oninput=()=>form[e.dataset.form]=e.value);
 const on=(sel,fn)=>{const b=root.querySelector(sel);if(b)b.onclick=fn;};on('#walk-office',openOffice);on('#expand-office',()=>act(()=>{E.buy(state,'sqm');E.useItem(state,'sqm');}));on('#rename-company',()=>act(()=>state.name=root.querySelector('#company-name').value.trim().slice(0,34)||'Моя компания'));on('#market-buy',()=>act(()=>E.buy(state,asset,+form.qty,'market')));on('#market-sell',()=>act(()=>E.sellMarket(state,asset,+form.qty)));on('#limit-buy',()=>act(()=>E.listOrder(state,asset,'buy',+form.qty,+form.limit)));on('#limit-sell',()=>act(()=>E.listOrder(state,asset,'sell',+form.qty,+form.limit)));on('#open-position',()=>act(()=>E.openPosition(state,asset,form.side,+form.margin,+form.leverage)));on('#auction-bid',()=>act(()=>E.bidAuction(state)));on('#create-clan',()=>act(()=>E.joinClan(state,root.querySelector('#clan-name').value)));on('#join-clan',()=>act(()=>E.joinClan(state,'Северный кластер','join')));on('#add-member',()=>act(()=>E.addClanMember(state)));on('#leave-clan',()=>act(()=>E.leaveClan(state)));on('#start-war',()=>act(()=>E.startWar(state)));const select=root.querySelector('#asset-selector');if(select){if(!listing().some(p=>p.id===asset)){asset=listing()[0]?.id||'ssd';form.limit=String(Math.round(E.price(state,asset)));render();return;}select.onchange=e=>{asset=e.target.value;form.limit=String(Math.round(E.price(state,asset)));render();};}}
 function live(){root.querySelectorAll('[data-cash]').forEach(e=>e.innerHTML=fmt(state.cash)+' <small>CR</small>');root.querySelectorAll('[data-power]').forEach(e=>e.textContent=fmt(E.power(state)));root.querySelectorAll('[data-until]').forEach(e=>e.textContent=time(+e.dataset.until-state.time));root.querySelectorAll('[data-equity]').forEach(e=>{const p=state.positions.find(p=>p.pid===e.dataset.equity);e.textContent=p?'Капитал '+fmt(E.positionEquity(state,p))+' CR':'Ликвидировано';});const price=root.querySelector('[data-price]');if(price)price.innerHTML=fmt(E.price(state,asset))+' <small>CR</small>';const ob=root.querySelector('#live-book');if(ob)ob.innerHTML=book();const ch=root.querySelector('#chart-zone');if(ch)ch.innerHTML=chart();const job=root.querySelector('.case-progress');if(job){const j=state.jobs.find(j=>!j.done);job.innerHTML=j?jobStatus(j):'<span>Кейс завершён или команда свободна. Выручка на счету.</span>';}}
 function draw(now){if(disposed)return;raf=requestAnimationFrame(draw);const dt=Math.min(.1,(now-last)/1000);last=now;if(document.hidden||document.querySelector('dialog[open]'))return;const lootBefore=state.loot.length;E.tickTycoon(state,dt*state.speed);if(state.loot.length>lootBefore){toast('Клановый кейс: '+E.item(state.loot[0].id).name+'! Предмет на складе.');audio?.success();if(view==='clans')render();}refreshTime+=dt;saveTime+=dt;if(refreshTime>1){refreshTime=0;live();}if(saveTime>5){saveTime=0;save();if(!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)&&!dialog)render();}}
 const pagehide=()=>save();window.addEventListener('pagehide',pagehide);render();if(openAt==='walk')openOffice();else if(openAt==='ssd'||openAt==='ram')installItem(openAt);raf=requestAnimationFrame(draw);return()=>{disposed=true;save();cancelAnimationFrame(raf);worldCleanup?.();dialogCleanup?.();dialogCleanup=null;if(dialog){dialog.remove();dialog=null;}window.removeEventListener('pagehide',pagehide);clearTimeout(noticeTimer);document.querySelector('#tycoon-toast')?.remove();};
}
